const seen = new Set<number>();
const targets: { number: number; login: string }[] = [];
const skipped: unknown[] = [];

const asArray = (r: any): any[] =>
  Array.isArray(r) ? r : Array.isArray(r?.items) ? r.items : Array.isArray(r?.issues) ? r.issues : [];

for (let page = 1; page <= 50; page++) {
  const res: any = await tools.list_issues({ repo: "acme/web", state: "open", label: "perf", page });
  const items = asArray(res);
  if (items.length === 0) break;
  for (const it of items) {
    const num = Number(it.number);
    if (seen.has(num)) continue;
    seen.add(num);
    const labels = (it.labels ?? []).map((l: any) => (typeof l === "string" ? l : l?.name));
    const hasPerf = labels.includes("perf");
    const a = it.assignee ?? (Array.isArray(it.assignees) ? it.assignees[0] : undefined);
    const login = typeof a === "string" ? a : a?.login;
    if (it.pull_request || !hasPerf || it.state !== undefined && it.state !== "open" || !login) {
      skipped.push({ number: num, labels, assignee: login ?? null, state: it.state });
      continue;
    }
    targets.push({ number: num, login });
  }
  if (items.length < 50) break;
}

const posted: unknown[] = [];
for (const t of targets) {
  const r = await tools.post_comment({ repo: "acme/web", number: t.number, body: `ping @${t.login}` });
  posted.push({ number: t.number, login: t.login, result: r });
}

return { targets, skipped, posted };
